703	    /**
704	     * Immutable structured record of a successful owner creation, serialized as a single JSON object
705	     * to the {@code AUDIT} logger alongside the human-readable audit line. The {@code memberId}
706	     * field carries the owner's primary identifier (see {@link #primaryIdentifier(Owner)}).
707	     */
708	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
709	                                     Integer membershipLevel) {
710	
711	        /**
712	         * The schema version of the structured {@code OWNER_CREATED} audit event. Version {@code 2}
713	         * accompanies the version-2 owner identity: the {@code memberId} carried here is the version-2
714	         * member id, and the event is stamped with {@code schemaVersion} 2.
715	         */
716	        private static final int SCHEMA_VERSION = 2;
717	
718	        String toJson() {
719	            return "{\"seq\":" + seq
720	                + ",\"schemaVersion\":" + SCHEMA_VERSION
721	                + ",\"ownerId\":" + ownerId
722	                + ",\"memberId\":" + jsonString(memberId)
723	                + ",\"membershipLevel\":" + membershipLevel
724	                + ",\"event\":\"OWNER_CREATED\"}";
725	        }
726	
727	        private static String jsonString(String value) {
728	            if (value == null) {
729	                return "null";
730	            }
731	            StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
732	            for (int i = 0; i < value.length(); i++) {
733	                char c = value.charAt(i);
734	                switch (c) {
735	                    case '"' -> sb.append("\\\"");
736	                    case '\\' -> sb.append("\\\\");
737	                    case '\n' -> sb.append("\\n");
738	                    case '\r' -> sb.append("\\r");
739	                    case '\t' -> sb.append("\\t");
740	                    default -> {
741	                        if (c < 0x20) {
742	                            sb.append(String.format("\\u%04x", (int) c));
743	                        } else {
744	                            sb.append(c);
745	                        }
746	                    }
747	                }
748	            }
749	            return sb.append('"').toString();
750	        }
751	    }
