86	    /**
87	     * Known disposable email service names, matched as a whole dot-separated label anywhere in an
88	     * owner's email domain to detect a domain that is <em>disposable-adjacent</em>. These are the base
89	     * labels of the disposable domains rejected outright at creation ({@code mailinator.com},
90	     * {@code tempmail.com}, {@code guerrillamail.com}); a domain that carries one of these labels but
91	     * is not itself on the exact blocklist (a subdomain such as {@code mail.mailinator.com} or a
92	     * different TLD such as {@code tempmail.net}) evaded the blocklist yet is still risky.
93	     */
94	    java.util.Set<String> DISPOSABLE_ADJACENT_LABELS = java.util.Set.of(
95	        "mailinator", "tempmail", "guerrillamail");
