97	    /**
98	     * Derives an owner's risk flag: {@code true} when any of the following hold, otherwise
99	     * {@code false}. The owner is a possible duplicate ({@link Owner#getPossibleDuplicate()}), the
100	     * owner's email domain is {@link #disposableAdjacentEmail(Owner) disposable-adjacent}, or the
101	     * owner's city was over its soft capacity when created ({@link Owner#getCapacityWarning()}).
102	     *
103	     * @param owner the owner to derive the risk flag for
104	     * @return {@code true} when the owner is a possible duplicate, has a disposable-adjacent email
105	     *     domain, or was created over its city's soft capacity; otherwise {@code false}
106	     */
107	    default Boolean riskFlag(Owner owner) {
108	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
109	            || Boolean.TRUE.equals(owner.getCapacityWarning())
110	            || disposableAdjacentEmail(owner);
111	    }
