113	    /**
114	     * Determines whether an owner's email domain is <em>disposable-adjacent</em>: any of the domain's
115	     * dot-separated labels (compared case-insensitively) matches a known disposable email service name
116	     * ({@link #DISPOSABLE_ADJACENT_LABELS}). This catches domains that evade the exact disposable
117	     * blocklist enforced at creation, such as a subdomain ({@code mail.mailinator.com}) or a variant
118	     * TLD ({@code tempmail.net}). An owner with no email, or a value without a domain part, is not
119	     * disposable-adjacent.
120	     *
121	     * @param owner the owner whose email domain is examined
122	     * @return {@code true} when the email domain carries a known disposable-service label, otherwise
123	     *     {@code false}
124	     */
125	    default boolean disposableAdjacentEmail(Owner owner) {
126	        String email = owner.getEmail();
127	        if (email == null || email.isBlank()) {
128	            return false;
129	        }
130	        int at = email.lastIndexOf('@');
131	        if (at < 0 || at == email.length() - 1) {
132	            return false;
133	        }
134	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
135	        for (String label : domain.split("\\.")) {
136	            if (DISPOSABLE_ADJACENT_LABELS.contains(label)) {
137	                return true;
138	            }
139	        }
140	        return false;
141	    }
