182	    default String ageBand(Owner owner) {
183	        java.time.LocalDate birthDate = owner.getBirthDate();
184	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
185	        if (birthDate == null || registrationDate == null) {
186	            return null;
187	        }
188	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
