207	    /**
208	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
209	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
210	     * normalizing telephones into E.164 form.
211	     */
212	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
213	
214	    /**
215	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
216	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
217	     * The country code is taken as the longest recognized prefix (see
218	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
219	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
220	     * is returned unchanged.
221	     *
222	     * @param owner the owner to format the telephone display for
223	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
224	     *     digit string
225	     */
226	    default String telephoneDisplay(Owner owner) {
227	        String telephone = owner.getTelephone();
228	        if (telephone == null || !telephone.startsWith("+")) {
229	            return telephone;
230	        }
231	        String digits = telephone.substring(1);
232	        if (!digits.matches("[0-9]+")) {
233	            return telephone;
234	        }
235	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
236	            .filter(digits::startsWith)
237	            .max(java.util.Comparator.comparingInt(String::length))
238	            .orElseGet(() -> digits.substring(0, 1));
239	        String national = digits.substring(countryCode.length());
240	        StringBuilder sb = new StringBuilder("+").append(countryCode);
241	        for (int i = 0; i < national.length(); i += 3) {
242	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
243	        }
244	        return sb.toString();
245	    }
