247	    /**
248	     * Fixed region-to-inclusive-4-digit-postcode-range table: {@code NSW 2000-2099}, {@code VIC
249	     * 3000-3099}, {@code QLD 4000-4099}. Mirrors the canonical ranges used to derive an owner's region
250	     * from its postcode.
251	     */
252	    java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
253	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
254	
255	    /**
256	     * Derives an owner's plain region code, preferring the postcode over the city. The postcode is
257	     * looked up against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC
258	     * 3000-3099}, {@code QLD 4000-4099}); only when the postcode is absent or in no known range does
259	     * the derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
260	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). The result is {@code "UNKNOWN"} when neither the
261	     * postcode nor the city resolves to a region. This is the plain region used for the user-facing
262	     * {@code locality}, {@code timezone} and the owner segment - it never carries the
263	     * {@link #IDENTITY_VERSION_TAG}, which is confined to the identifiers.
264	     *
265	     * @param owner the owner to derive the region for
266	     * @return the region code {@code NSW}, {@code VIC}, {@code QLD} or {@code UNKNOWN}
267	     */
268	    default String region(Owner owner) {
269	        String fromPostcode = regionFromPostcode(owner.getPostcode());
270	        if (fromPostcode != null) {
271	            return fromPostcode;
272	        }
273	        return regionFromCity(owner.getCity());
274	    }
275	
276	    private String regionFromPostcode(String postcode) {
277	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
278	            return null;
279	        }
280	        int value = Integer.parseInt(postcode);
281	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
282	            int[] range = entry.getValue();
283	            if (value >= range[0] && value <= range[1]) {
284	                return entry.getKey();
285	            }
286	        }
287	        return null;
288	    }
289	
290	    private String regionFromCity(String city) {
291	        if (city == null) {
292	            return "UNKNOWN";
293	        }
294	        return switch (city) {
295	            case "Sydney" -> "NSW";
296	            case "Melbourne" -> "VIC";
297	            case "Brisbane" -> "QLD";
298	            default -> "UNKNOWN";
299	        };
300	    }
