302	    /**
303	     * Derives an owner's locality: the plain {@link #region(Owner) region code} derived from the
304	     * owner's postcode (falling back to the city). The locality is <em>not</em> an identifier, so it
305	     * remains the plain region (for example {@code "NSW"}) and never carries the version-2
306	     * {@link #IDENTITY_VERSION_TAG}. The result is {@code "UNKNOWN"} when no region resolves.
307	     *
308	     * @param owner the owner to derive the locality for
309	     * @return the plain region code, or {@code "UNKNOWN"}
310	     */
311	    default String locality(Owner owner) {
312	        return region(owner);
