316	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
317	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
318	     */
319	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
320	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
321	
322	    /**
323	     * The regions considered {@code METRO} for the purposes of {@link #ownerSegment(Owner)}: the
324	     * known regions {@code NSW}, {@code VIC} and {@code QLD}. Any other locality is {@code REGIONAL}.
325	     */
326	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
