328	    /**
329	     * Derives an owner's segment, formatted {@code <TIER>_<AREA>}. {@code TIER} is {@code PREMIUM}
330	     * when the owner's {@link #membershipLevel(Owner) membership level} is {@code 3} or more,
331	     * otherwise {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's
332	     * {@link #locality(Owner) locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
333	     * otherwise {@code REGIONAL}. The result is one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
334	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
335	     *
336	     * @param owner the owner to derive the segment for
337	     * @return the {@code <TIER>_<AREA>} owner segment
338	     */
339	    default String ownerSegment(Owner owner) {
340	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
341	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
342	        return tier + "_" + area;
