345	    /**
346	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
347	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
348	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
349	     * the field is omitted from the response.
350	     *
351	     * @param owner the owner to derive the timezone for
352	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
353	     */
354	    default String timezone(Owner owner) {
355	        return REGION_TIMEZONES.get(locality(owner));
356	    }
