358	    /**
359	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
360	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
361	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
362	     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
363	     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
364	     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
365	     * points.
366	     *
367	     * @param owner the owner to derive the membership points for
368	     * @return the membership points, {@code 0} or more
369	     */
370	    default Integer membershipPoints(Owner owner) {
371	        return membershipPoints(owner, owner.getHouseholdMemberCount());
372	    }
373	
374	    /**
375	     * Derives an owner's membership points as {@link #membershipPoints(Owner)}, but scoring the
376	     * household bonus against the supplied household member count rather than the owner's stored one.
377	     * Used to evaluate an existing household member's current standing against the household size that
378	     * includes a newly joining owner.
379	     *
380	     * @param owner the owner to derive the membership points for
381	     * @param householdMemberCount the household member count to score the household bonus against
382	     * @return the membership points, {@code 0} or more
383	     */
384	    private int membershipPoints(Owner owner, Integer householdMemberCount) {
385	        int points = 0;
386	        String email = owner.getEmail();
387	        if (email != null && !email.isBlank()) {
388	            points += 2;
389	        }
390	        Integer namesakeCount = owner.getNamesakeCount();
391	        if (namesakeCount != null && namesakeCount == 0) {
392	            points += 1;
393	        }
394	        if (householdMemberCount != null && householdMemberCount >= 3) {
395	            points += 2;
396	        }
397	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
398	        long tenureFiscalYears = registrationDate == null ? 0
399	            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
400	        if (tenureFiscalYears > 1) {
401	            points += 3;
402	        }
403	        return points;
404	    }
