406	    /**
407	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
408	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
409	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more. The points-derived
410	     * level is then capped by the owner's {@link Owner#getMembershipLevelCap() membership level cap}
411	     * when one was recorded at creation - a new owner's level can never exceed one above the highest
412	     * level among the household members that already existed. When no cap was recorded (the owner had
413	     * no existing household member) the points-derived level is returned unchanged.
414	     *
415	     * @param owner the owner to derive the membership level for
416	     * @return the membership level, between {@code 1} and {@code 4}
417	     */
418	    default Integer membershipLevel(Owner owner) {
419	        return cappedLevel(owner, levelForPoints(membershipPoints(owner)));
420	    }
421	
422	    /**
423	     * Derives an existing household member's current membership level as it would stand in a household
424	     * of the supplied size, so a newly joining owner's level ceiling can be measured against the
425	     * up-to-date standing of the members it joins. The member's own {@link Owner#getMembershipLevelCap()
426	     * cap} still applies.
427	     *
428	     * @param owner the existing household member to evaluate
429	     * @param householdMemberCount the household member count that includes the joining owner
430	     * @return the member's capped membership level for that household size, between {@code 1} and {@code 4}
431	     */
432	    default Integer householdMemberLevel(Owner owner, int householdMemberCount) {
433	        return cappedLevel(owner, levelForPoints(membershipPoints(owner, householdMemberCount)));
434	    }
435	
436	    /**
437	     * Applies an owner's {@link Owner#getMembershipLevelCap() membership level cap} to a points-derived
438	     * level: the level is returned unchanged when no cap was recorded, otherwise it is clamped to the
439	     * cap.
440	     *
441	     * @param owner the owner whose cap is applied
442	     * @param level the uncapped points-derived level
443	     * @return the capped level
444	     */
445	    private Integer cappedLevel(Owner owner, int level) {
446	        Integer cap = owner.getMembershipLevelCap();
447	        if (cap != null && level > cap) {
448	            return cap;
449	        }
450	        return level;
451	    }
452	
453	    /**
454	     * Maps membership points to a numeric level: level {@code 1} for {@code 0}-{@code 1} points,
455	     * {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}, and {@code 4} for
456	     * {@code 6} or more.
457	     *
458	     * @param points the membership points
459	     * @return the points-based membership level, between {@code 1} and {@code 4}
460	     */
461	    private Integer levelForPoints(int points) {
462	        if (points <= 1) {
463	            return 1;
464	        }
465	        if (points <= 3) {
466	            return 2;
467	        }
468	        if (points <= 5) {
469	            return 3;
470	        }
471	        return 4;
472	    }
