488	    /**
489	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
490	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
491	     * December belongs to the following calendar year's fiscal year and a date in January through
492	     * June belongs to its own calendar year's fiscal year.
493	     *
494	     * @param date the date to compute the fiscal year for
495	     * @return the fiscal year as a four-digit calendar year
496	     */
497	    private int fiscalYearValue(java.time.LocalDate date) {
498	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
499	    }
