501	    /**
502	     * Derives an owner's version-2 household identifier: the first 12 hex characters of the SHA-256
503	     * digest over {@code V2|<normalizedLastName>|<postcode>}, where the leading {@code V2} is the
504	     * fixed {@link #IDENTITY_VERSION_TAG}, the last name is normalized case-insensitively with
505	     * collapsed whitespace and a missing postcode contributes the empty string. Mixing in the version
506	     * tag rederives the identifier under version 2 so it never reproduces a version-1 value. Because
507	     * it is otherwise derived deterministically from the last name and postcode, every owner that
508	     * shares those two fields receives the same value - including owners created via the
509	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
510	     *
511	     * @param owner the owner to derive the household identifier for
512	     * @return the 12 upper-case hex character household identifier, never blank
513	     */
514	    default String householdId(Owner owner) {
515	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
516	        String key = IDENTITY_VERSION_TAG + '|' + normalizeHouseholdField(owner.getLastName())
517	            + '|' + postcode;
518	        try {
519	            byte[] digest = MessageDigest.getInstance("SHA-256")
520	                .digest(key.getBytes(StandardCharsets.UTF_8));
521	            StringBuilder sb = new StringBuilder(12);
522	            for (int i = 0; i < 6; i++) {
523	                sb.append(String.format("%02X", digest[i]));
524	            }
525	            return sb.toString();
526	        }
527	        catch (NoSuchAlgorithmException ex) {
528	            throw new IllegalStateException("SHA-256 not available", ex);
529	        }
530	    }
531	
532	    /**
533	     * Derives an owner's version-2 identity key, into which all duplicate detection is consolidated.
534	     * The key is the full lower-case hex SHA-256 digest over
535	     * {@code V2|<normalizedTelephone>|<email or empty>|<soundex(lastName)>}: the leading {@code V2}
536	     * fixed {@link #IDENTITY_VERSION_TAG}, the owner's (already E.164 normalized) telephone, its
537	     * (already lower-cased) email or the empty string when none is held, and the {@link Soundex
538	     * Soundex} code of its last name. Mixing in the version tag rederives the key under version 2 so
539	     * it never reproduces a version-1 value. Two owners are duplicates only when their whole identity
540	     * keys are equal; because the telephone is part of the key, owners sharing a surname (same
541	     * soundex) but holding different telephones have different keys.
542	     *
543	     * @param owner the owner to derive the identity key for
544	     * @return the 64-character lower-case hex identity key
545	     */
546	    default String identityKey(Owner owner) {
547	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
548	        String email = owner.getEmail() == null ? "" : owner.getEmail();
549	        String key = IDENTITY_VERSION_TAG + '|' + telephone + '|' + email
550	            + '|' + Soundex.encode(owner.getLastName());
551	        try {
552	            byte[] digest = MessageDigest.getInstance("SHA-256")
553	                .digest(key.getBytes(StandardCharsets.UTF_8));
554	            StringBuilder sb = new StringBuilder(digest.length * 2);
555	            for (byte b : digest) {
556	                sb.append(String.format("%02x", b));
557	            }
558	            return sb.toString();
559	        }
560	        catch (NoSuchAlgorithmException ex) {
561	            throw new IllegalStateException("SHA-256 not available", ex);
562	        }
563	    }
