565	    /**
566	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
567	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
568	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
569	     *
570	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
571	     * conversion and apply it to unrelated String properties (last name, address, ...).
572	     */
573	    private String normalizeHouseholdField(String value) {
574	        if (value == null) {
575	            return "";
576	        }
577	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
578	    }
