235	    @Override
236	    @Transactional
237	    public void saveOwner(Owner owner) throws DataAccessException {
238	        if (owner.isNew() && owner.getMemberId() == null) {
239	            owner.setMemberId(generateMemberId(owner));
240	        }
241	        if (owner.isNew() && owner.getNamesakeCount() == null) {
242	            owner.setNamesakeCount(countNamesakes(owner));
243	        }
244	        if (owner.isNew() && owner.getHouseholdMemberCount() == null) {
245	            owner.setHouseholdMemberCount(countHouseholdMembers(owner));
246	        }
247	        ownerRepository.save(owner);
248	
249	    }
250	
251	    /**
252	     * Count the members of the new owner's household after this create: the existing owners
253	     * that share the given owner's last name (compared case-insensitively with collapsed
254	     * whitespace) and postcode - the same (last name, postcode) pair from which the household
255	     * identifier is derived - plus the owner being created. Invoked before the new owner is
256	     * persisted.
257	     */
258	    private int countHouseholdMembers(Owner owner) {
259	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
260	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
261	        long existing = ownerRepository.findAll().stream()
262	            .filter(other -> normalizeHouseholdField(other.getLastName()).equals(normalizedLastName)
263	                && postcode.equals(other.getPostcode() == null ? "" : other.getPostcode()))
264	            .count();
265	        return (int) existing + 1;
266	    }
267	
268	    /**
269	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields
270	     * can be compared case-insensitively with collapsed whitespace. A {@code null} value
271	     * normalizes to the empty string.
272	     */
273	    private String normalizeHouseholdField(String value) {
274	        if (value == null) {
275	            return "";
276	        }
277	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
278	    }
279	
280	    /**
281	     * Count the existing owners that share the given owner's first name and last name,
282	     * compared case-insensitively. Invoked before the new owner is persisted, so the
283	     * result is the number of namesakes that existed at the time of creation.
284	     */
285	    private int countNamesakes(Owner owner) {
286	        String firstName = owner.getFirstName();
287	        String lastName = owner.getLastName();
288	        if (firstName == null || lastName == null) {
289	            return 0;
290	        }
291	        return (int) ownerRepository.findAll().stream()
292	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
293	                && lastName.equalsIgnoreCase(existing.getLastName()))
294	            .count();
295	    }
296	
297	    /**
298	     * Build the owner's member id in the form '<REGION><FY><HASH8><CHK>' where REGION is the region
299	     * code derived from the owner's postcode (falling back to the city), FY is the 2-digit fiscal
300	     * year of the owner's business-day-adjusted registration date, HASH8 is the first 8 upper-case
301	     * hex characters of the SHA-256 digest over the owner's normalized telephone concatenated with
302	     * the owner's last name (the same HASH8 used by the region-and-hash identity), and CHK is a
303	     * single Luhn check digit computed over the digits of '<REGION><FY><HASH8>'. The identity is
304	     * derived entirely from the region, the fiscal year and the telephone/last-name hash.
305	     */
306	    private String generateMemberId(Owner owner) {
307	        String core = versionedRegion(owner) + fiscalYear2(owner) + hash8(owner);
308	        String base = core + luhnCheckDigit(core);
309	        return deduplicateMemberId(base);
310	    }
311	
312	    /**
313	     * The fixed version tag mixed into the region code used inside the version-2 member id, so the
314	     * member id (and every other version-2 identifier) differs from the value the same owner would
315	     * have produced under version 1 and no version-1 value recurs. The tag is confined to the
316	     * identifier: the plain {@link #regionFor(Owner) region} still feeds the user-facing locality,
317	     * timezone and owner segment.
318	     */
319	    private static final String IDENTITY_VERSION_TAG = "V2";
320	
321	    /**
322	     * Derive the version-2 region code used inside the member id: the plain
323	     * {@link #regionFor(Owner) region} prefixed with the fixed {@link #IDENTITY_VERSION_TAG}
324	     * (for example {@code NSW -> V2NSW}).
325	     */
326	    private String versionedRegion(Owner owner) {
327	        return IDENTITY_VERSION_TAG + regionFor(owner);
328	    }
329	
330	    /**
331	     * Ensure the computed member id is unique across existing owners. When the base id collides
332	     * with an existing owner's {@code memberId}, append {@code '-<n>'} with the smallest {@code n}
333	     * of 2 or more that makes it unique, and return that de-duplicated id.
334	     */
335	    private String deduplicateMemberId(String base) {
336	        Set<String> existing = ownerRepository.findAll().stream()
337	            .map(Owner::getMemberId)
338	            .filter(code -> code != null)
339	            .collect(java.util.stream.Collectors.toSet());
340	        if (!existing.contains(base)) {
341	            return base;
342	        }
343	        int n = 2;
344	        while (existing.contains(base + "-" + n)) {
345	            n++;
346	        }
347	        return base + "-" + n;
348	    }
349	
350	    /**
351	     * Compute the 2-digit (zero-padded) fiscal year of the owner's registration date. The fiscal
352	     * year starts on 1 July and is labelled by the calendar year in which it ends, so a date on or
353	     * after 1 July belongs to the next calendar year's fiscal year. Falls back to the current server
354	     * date when the owner has no registration date yet.
355	     */
356	    private String fiscalYear2(Owner owner) {
357	        java.time.LocalDate date = owner.getRegistrationDate() == null
358	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
359	        int fiscalYear = date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
360	        return String.format("%02d", fiscalYear % 100);
361	    }
362	
363	    /**
364	     * Compute a single Luhn check digit (0-9) over the digit characters contained in {@code value};
365	     * non-digit characters are ignored.
366	     */
367	    private int luhnCheckDigit(String value) {
368	        int sum = 0;
369	        boolean dbl = true;
370	        for (int i = value.length() - 1; i >= 0; i--) {
371	            char c = value.charAt(i);
372	            if (c < '0' || c > '9') {
373	                continue;
374	            }
375	            int d = c - '0';
376	            if (dbl) {
377	                d *= 2;
378	                if (d > 9) {
379	                    d -= 9;
380	                }
381	            }
382	            sum += d;
383	            dbl = !dbl;
384	        }
385	        return (10 - (sum % 10)) % 10;
386	    }
387	
388	    /**
389	     * Derive the owner's region, preferring the postcode over the city. The postcode is looked up
390	     * against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC 3000-3099},
391	     * {@code QLD 4000-4099}); only when the postcode is absent or falls in no known range does the
392	     * derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
393	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). The result is {@code "UNKNOWN"} when neither
394	     * the postcode nor the city resolves to a region.
395	     */
396	    private String regionFor(Owner owner) {
397	        String region = regionFromPostcode(owner.getPostcode());
398	        if (region != null) {
399	            return region;
400	        }
401	        return regionFromCity(owner.getCity());
402	    }
403	
404	    /**
405	     * Look up the canonical region for a postcode by its range ({@code NSW 2000-2099},
406	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code null} when the postcode is
407	     * absent, non-numeric or in no known range.
408	     */
409	    private String regionFromPostcode(String postcode) {
410	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
411	            return null;
412	        }
413	        int value = Integer.parseInt(postcode);
414	        if (value >= 2000 && value <= 2099) {
415	            return "NSW";
416	        }
417	        if (value >= 3000 && value <= 3099) {
418	            return "VIC";
419	        }
420	        if (value >= 4000 && value <= 4099) {
421	            return "QLD";
422	        }
423	        return null;
424	    }
425	
426	    /**
427	     * Look up the canonical region for a city using the fixed city-to-region table, returning
428	     * {@code "UNKNOWN"} when the city is absent or not in the table.
429	     */
430	    private String regionFromCity(String city) {
431	        if (city == null) {
432	            return "UNKNOWN";
433	        }
434	        return switch (city) {
435	            case "Sydney" -> "NSW";
436	            case "Melbourne" -> "VIC";
437	            case "Brisbane" -> "QLD";
438	            default -> "UNKNOWN";
439	        };
440	    }
441	
442	    /**
443	     * Compute the first 8 upper-case hex characters of the SHA-256 digest over the owner's
444	     * normalized telephone concatenated with the owner's last name.
445	     */
446	    private String hash8(Owner owner) {
447	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
448	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
449	        try {
450	            byte[] digest = MessageDigest.getInstance("SHA-256")
451	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
452	            StringBuilder sb = new StringBuilder(8);
453	            for (int i = 0; i < 4; i++) {
454	                sb.append(String.format("%02X", digest[i]));
455	            }
456	            return sb.toString();
457	        }
458	        catch (NoSuchAlgorithmException ex) {
459	            throw new IllegalStateException("SHA-256 not available", ex);
460	        }
461	    }
